{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.fees import late_fee"
  ],
  "tests": [
    {
      "name": "test_late_fee_example_from_task",
      "intent": "the example given in the task: 100.00 paid 7 days late with default 5-day grace period charges 2.00",
      "code": "# intent: the example given in the task: 100.00 paid 7 days late with default 5-day grace period charges 2.00\ndef test_late_fee_example_from_task():\n    assert late_fee(Decimal(\"100.00\"), 7) == Decimal(\"2.00\")\n"
    },
    {
      "name": "test_late_fee_grace_period_boundary",
      "intent": "days_late equal to grace_days results in zero fee",
      "code": "# intent: days_late equal to grace_days results in zero fee\ndef test_late_fee_grace_period_boundary():\n    assert late_fee(Decimal(\"100.00\"), 5) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_late_fee_one_day_beyond_grace",
      "intent": "one day beyond grace period charges exactly 1% of amount",
      "code": "# intent: one day beyond grace period charges exactly 1% of amount\ndef test_late_fee_one_day_beyond_grace():\n    assert late_fee(Decimal(\"100.00\"), 6) == Decimal(\"1.00\")\n"
    },
    {
      "name": "test_late_fee_zero_days_late",
      "intent": "zero days late results in zero fee",
      "code": "# intent: zero days late results in zero fee\ndef test_late_fee_zero_days_late():\n    assert late_fee(Decimal(\"100.00\"), 0) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_late_fee_custom_grace_period",
      "intent": "custom grace period is respected",
      "code": "# intent: custom grace period is respected\ndef test_late_fee_custom_grace_period():\n    assert late_fee(Decimal(\"100.00\"), 10, grace_days=3) == Decimal(\"7.00\")\n"
    },
    {
      "name": "test_late_fee_negative_days_late",
      "intent": "negative days_late raises ValueError",
      "code": "# intent: negative days_late raises ValueError\ndef test_late_fee_negative_days_late():\n    with pytest.raises(ValueError):\n        late_fee(Decimal(\"100.00\"), -1)\n"
    }
  ]
}
